func TestResolveGitHubAlert(t *testing.T) {
	t.Parallel()

	c := qt.New(t)

	tests := []struct {
		input    string
		expected string
	}{
		{
			input:    "[!NOTE]",
			expected: "note",
		},
		{
			input:    "[!WARNING]",
			expected: "warning",
		},
		{
			input:    "[!TIP]",
			expected: "tip",
		},
		{
			input:    "[!IMPORTANT]",
			expected: "important",
		},
		{
			input:    "[!CAUTION]",
			expected: "caution",
		},
		{
			input:    "[!FOO]",
			expected: "",
		},
	}

	for _, test := range tests {
		c.Assert(resolveGitHubAlert("<p>"+test.input), qt.Equals, test.expected)
	}
}

